                @Override public void writeBinary(byte[] data, int offset, int len) throws IOException {}
                @Override public void writeArray(int[] array, int offset, int length) throws IOException {}
                @Override public void writeArray(long[] array, int offset, int length) throws IOException {}
                @Override public void writeArray(double[] array, int offset, int length) throws IOException {}
                @Override public void writeFieldId(long id) throws IOException {}
                @Override public void writeStartArray(int size) throws IOException {}
                @Override public void writeStartObject(Object forValue) throws IOException {}
                @Override public void setCodec(ObjectCodec oc) {}
                @Override public ObjectCodec getCodec() {}
                @Override public com.fasterxml.jackson.core.versions.Version version() { return null; }
                @Override public JsonGenerator enable(com.fasterxml.jackson.core.JsonParser.Feature f) { return null; }
                @Override public JsonGenerator disable(com.fasterxml.jackson.core.JsonParser.Feature f) { return null; }
                @Override public boolean isEnabled(com.fasterxml.jackson.core.JsonParser.Feature f) { return false; }
                @Override public int getFeatureMask() { return 0; }
                @Override public void setFeatureMask(int values) {}
                @Override public void setSchema(com.fasterxml.jackson.core.schema.FormatSchema schema) {}
                @Override public com.fasterxml.jackson.core.schema.FormatSchema getSchema() { return null; }
                @Override public void setPrettyPrinter(com.fasterxml.jackson.core.util.PrettyPrinter pp) {}
                @Override public com.fasterxml.jackson.core.util.PrettyPrinter getPrettyPrinter() { return null; }
                @Override public JsonGenerator useDefaultPrettyPrinter() { return null; }
                @Override public void setHighestNonEscapedChar(int charCode) {}
                @Override public int getHighestEscapedChar() { return 0; }
                @Override public com.fasterxml.jackson.core.util.CharacterEscapes getCharacterEscapes() { return null; }
                @Override public void setCharacterEscapes(com.fasterxml.jackson.core.util.CharacterEscapes esc) {}
                @Override public void setRootValueSeparator(com.fasterxml.jackson.core.io.SerializableString sep) {}
                @Override public Object getOutputTarget() { return null; }
                @Override public int getOutputBuffered() { return 0; }
                @Override public Object getCurrentValue() { return null; }
                @Override public void setCurrentValue(Object v) {}
                @Override public boolean canUseSchema(com.fasterxml.jackson.core.schema.FormatSchema schema) { return false; }
                @Override public boolean canWriteObjectId() { return false; }
                @Override public boolean canWriteTypeId() { return false; }
                @Override public boolean canWriteBinaryNatively() { return false; }
                @Override public boolean canOmitFields() { return false; }
                @Override public boolean canWriteFormattedNumbers() { return false; }
            };

            realGenerator.writeEmbeddedObject(testObject);
            Assert.fail("Expected JsonGenerationException to be thrown");
        } catch (JsonGenerationException e) {
            Assert.assertEquals("No native support for writing embedded objects", e.getMessage());
            Assert.assertEquals(realGenerator, e.getGenerator());
        } catch (IOException e) {
            Assert.fail("Expected JsonGenerationException, but caught " + e.getClass().getSimpleName());
        }
    }

